import { onMounted, onUnmounted, ref } from "vue";

const RELOAD_AT_KEY = "planner.pwa-reloaded-at";

/** The service worker generated by @vite-pwa/nuxt at the app root. */
const SW_URL = "/sw.js";

/** Minimum delay between two automatic PWA reloads (loop guard). */
export const RELOAD_LOOP_GUARD_MS = 60 * 1000;

/** How often a long-lived tab re-checks the service worker for updates. */
export const UPDATE_CHECK_INTERVAL_MS = 60 * 60 * 1000;

/**
 * Pure decision for reloading when the service worker takes over a page it
 * already controlled (a genuine update, not the first `clientsClaim`): a
 * reload must not steal focus from an open dialog and must not loop.
 */
export function shouldAutoReload({
  hadController,
  hasOpenDialog,
  lastReloadAt,
  now,
}: {
  hadController: boolean;
  hasOpenDialog: boolean;
  lastReloadAt: number | null;
  now: number;
}): boolean {
  if (!hadController) return false;
  if (hasOpenDialog) return false;
  if (lastReloadAt !== null && now - lastReloadAt < RELOAD_LOOP_GUARD_MS) {
    return false;
  }
  return true;
}

function readLastReloadAt(): number | null {
  try {
    const raw = sessionStorage.getItem(RELOAD_AT_KEY);
    if (raw === null) return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
  } catch {
    return null;
  }
}

function hasOpenDialog(): boolean {
  return !!document.querySelector("dialog[open]");
}

/**
 * PWA update flow: a tab that is never reloaded never re-checks sw.js, so
 * the app would keep running a stale precached shell forever. This owns the
 * whole update lifecycle:
 * - registers the service worker when no registration exists yet (the
 *   @vite-pwa/nuxt client plugin is disabled: its autoUpdate handler
 *   hard-reloads on every takeover with no guards);
 * - `registration.update()` every hour and when the tab becomes visible, so
 *   an update is actually detected;
 * - on `controllerchange` (the new worker took over) it reloads the page
 *   when that is safe, or falls back to a dismissible banner the user can
 *   act on. The first `clientsClaim` of a previously uncontrolled page is
 *   not an update and is ignored.
 */
export function useAppUpdate() {
  const showUpdateBanner = ref(false);
  let checkTimer: ReturnType<typeof setInterval> | null = null;
  let registration: ServiceWorkerRegistration | null = null;
  let hadController = false;

  async function checkForUpdate() {
    try {
      await registration?.update();
    } catch {
      // Offline or transient failure: the next check retries
    }
  }

  function onVisibilityChange() {
    if (!document.hidden) {
      checkForUpdate();
    }
  }

  function onControllerChange() {
    // First claim of a previously uncontrolled page is not an update
    if (!hadController) return;
    const now = Date.now();
    if (
      shouldAutoReload({
        hadController,
        hasOpenDialog: hasOpenDialog(),
        lastReloadAt: readLastReloadAt(),
        now,
      })
    ) {
      try {
        sessionStorage.setItem(RELOAD_AT_KEY, String(now));
      } catch {
        // Storage unavailable: reload anyway, the guard is best-effort
      }
      window.location.reload();
      return;
    }
    showUpdateBanner.value = true;
  }

  onMounted(async () => {
    if (!("serviceWorker" in navigator)) return;
    hadController = !!navigator.serviceWorker.controller;
    navigator.serviceWorker.addEventListener(
      "controllerchange",
      onControllerChange,
    );
    try {
      registration =
        (await navigator.serviceWorker.getRegistration()) ??
        (await navigator.serviceWorker.register(SW_URL, { scope: "/" }));
    } catch {
      // No service worker: the app still works, just without offline support
    }
    if (registration) {
      checkTimer = setInterval(checkForUpdate, UPDATE_CHECK_INTERVAL_MS);
      document.addEventListener("visibilitychange", onVisibilityChange);
    }
  });

  onUnmounted(() => {
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker.removeEventListener(
        "controllerchange",
        onControllerChange,
      );
    }
    if (checkTimer) {
      clearInterval(checkTimer);
      checkTimer = null;
    }
    document.removeEventListener("visibilitychange", onVisibilityChange);
  });

  return { showUpdateBanner };
}
